import {
  Injectable,
  NotFoundException,
  ConflictException,
  Logger,
  Optional,
  Inject,
} from '@nestjs/common';
import { PrismaService } from '../../infrastructure/database/prisma.service';
import { CreateTenantDto, UpdateTenantDto } from './dto/tenant.dto';
import { TenantStatus } from '@prisma/client';
import { TierProvisioningService } from '../tiers/services/tier-provisioning.service';

export interface TierChangePreview {
  tenantId: string;
  tenantName: string;
  currentTier: {
    id: string;
    name: string;
    slug: string;
    maxAgents: number;
  };
  targetTier: {
    id: string;
    name: string;
    slug: string;
    maxAgents: number;
  };
  usage: {
    selectedAgents: number;
    selectedDepartments: number;
  };
  compatibility: {
    canChange: boolean;
    blockingReasons: string[];
  };
  impact: {
    agentsToProvision: Array<{
      templateId: string;
      templateName: string;
      slotType: string;
    }>;
    departmentsToProvision: Array<{
      templateId: string;
      templateName: string;
      slotType: string;
    }>;
    tierLinkedAgentsOutsideTargetPolicy: Array<{
      id: string;
      name: string;
      templateId: string | null;
    }>;
    tierLinkedDepartmentsOutsideTargetPolicy: Array<{
      id: string;
      name: string;
      templateId: string | null;
    }>;
  };
}

@Injectable()
export class TenantsService {
  private readonly logger = new Logger(TenantsService.name);
  constructor(
    private readonly prisma: PrismaService,
    @Optional()
    @Inject('TIER_PROVISIONING')
    private readonly provisioningService?: TierProvisioningService,
  ) {}

  async findAll(page = 1, limit = 20, search?: string) {
    const skip = (page - 1) * limit;

    const where: any = {};
    if (search) {
      where.OR = [
        { name: { contains: search, mode: 'insensitive' } },
        { slug: { contains: search, mode: 'insensitive' } },
      ];
    }

    const [items, total] = await Promise.all([
      this.prisma.tenant.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdAt: 'desc' },
        include: { tier: true },
      }),
      this.prisma.tenant.count({ where }),
    ]);
    return { items, total, page, limit };
  }

  async findOne(id: string) {
    const tenant = await this.prisma.tenant.findUnique({
      where: { id },
      include: { tier: true },
    });
    if (!tenant) throw new NotFoundException(`Tenant ${id} not found`);
    return tenant;
  }

  async create(dto: CreateTenantDto) {
    const existing = await this.prisma.tenant.findUnique({
      where: { slug: dto.slug },
    });
    if (existing) throw new ConflictException('Slug already taken');

    // Get default tier if not specified
    let tierId = dto.tierId;
    if (!tierId) {
      const defaultTier = await this.prisma.tier.findFirst({
        where: { isDefault: true },
      });
      if (!defaultTier) {
        throw new ConflictException('No default tier configured');
      }
      tierId = defaultTier.id;
    }

    // Verify tier exists
    const tier = await this.prisma.tier.findUnique({ where: { id: tierId } });
    if (!tier) {
      throw new NotFoundException(`Tier ${tierId} not found`);
    }

    // Create tenant with tier
    const tenant = await this.prisma.tenant.create({
      data: {
        name: dto.name,
        slug: dto.slug,
        status: TenantStatus.TRIAL,
        tierId,
        logoUrl: dto.logoUrl,
        website: dto.website,
        industry: dto.industry,
      },
      include: { tier: true },
    });

    // Auto-provision agents based on tier
    if (this.provisioningService) {
      try {
        const result = await this.provisioningService.provisionAgents(
          tenant.id,
          tenant.tierId,
        );
        this.logger.log(
          `Tenant ${tenant.slug} provisioned with ${result.agentsProvisioned} agents`,
        );
      } catch (error) {
        this.logger.error(
          `Failed to provision agents for tenant ${tenant.id}: ${(error as Error).message}`,
          (error as Error).stack,
        );
        // Don't fail tenant creation if provisioning fails
        // Admin can manually provision later
      }
    }

    this.logger.log(`Tenant created: ${tenant.slug} on tier ${tier.name}`);
    return tenant;
  }

  async update(id: string, dto: UpdateTenantDto) {
    await this.findOne(id);

    // Prevent changing tierId directly - use changeTier instead
    const { tierId, ...updateData } = dto as any;

    return this.prisma.tenant.update({
      where: { id },
      data: updateData,
      include: { tier: true },
    });
  }

  async previewTierChange(
    tenantId: string,
    newTierId: string,
  ): Promise<TierChangePreview> {
    const tenant = await this.findOne(tenantId);

    const newTier = await this.prisma.tier.findUnique({
      where: { id: newTierId },
    });
    if (!newTier) {
      throw new NotFoundException(`Tier ${newTierId} not found`);
    }

    const [
      selectedAgents,
      selectedDepartments,
      targetAgentPool,
      targetDepartmentPool,
    ] = await Promise.all([
      this.prisma.agent.findMany({
        where: { tenantId, isSelected: true },
        select: {
          id: true,
          name: true,
          templateId: true,
          tierAgentPoolId: true,
          deployedFromTierId: true,
        },
      }),
      this.prisma.department.findMany({
        where: { tenantId, isSelected: true },
        select: {
          id: true,
          name: true,
          templateId: true,
          tierDepartmentPoolId: true,
          deployedFromTierId: true,
        },
      }),
      this.prisma.tierAgentPool.findMany({
        where: { tierId: newTierId },
        include: { template: true },
        orderBy: { slot: 'asc' },
      }),
      this.prisma.tierDepartmentPool.findMany({
        where: { tierId: newTierId },
        include: { departmentTemplate: true },
        orderBy: { slot: 'asc' },
      }),
    ]);

    const blockingReasons: string[] = [];
    if (selectedAgents.length > newTier.maxAgents) {
      blockingReasons.push(
        `Tenant has ${selectedAgents.length} selected agents but target tier allows only ${newTier.maxAgents}`,
      );
    }

    const targetAgentTemplateIds = new Set(
      targetAgentPool.map((slot) => slot.templateId),
    );
    const targetDepartmentTemplateIds = new Set(
      targetDepartmentPool.map((slot) => slot.departmentTemplateId),
    );

    const selectedAgentTemplateIds = new Set(
      selectedAgents
        .map((agent) => agent.templateId)
        .filter((templateId): templateId is string => Boolean(templateId)),
    );
    const selectedDepartmentTemplateIds = new Set(
      selectedDepartments
        .map((department) => department.templateId)
        .filter((templateId): templateId is string => Boolean(templateId)),
    );

    const agentsToProvision = targetAgentPool
      .filter(
        (slot) =>
          slot.slotType === 'FIXED' &&
          !selectedAgentTemplateIds.has(slot.templateId),
      )
      .map((slot) => ({
        templateId: slot.templateId,
        templateName: slot.template?.name ?? 'Unknown Template',
        slotType: slot.slotType,
      }));

    const departmentsToProvision = targetDepartmentPool
      .filter(
        (slot) =>
          slot.slotType === 'FIXED' &&
          !selectedDepartmentTemplateIds.has(slot.departmentTemplateId),
      )
      .map((slot) => ({
        templateId: slot.departmentTemplateId,
        templateName: slot.departmentTemplate?.name ?? 'Unknown Template',
        slotType: slot.slotType,
      }));

    const tierLinkedAgentsOutsideTargetPolicy = selectedAgents
      .filter(
        (agent) =>
          (agent.tierAgentPoolId || agent.deployedFromTierId) &&
          agent.templateId &&
          !targetAgentTemplateIds.has(agent.templateId),
      )
      .map((agent) => ({
        id: agent.id,
        name: agent.name,
        templateId: agent.templateId,
      }));

    const tierLinkedDepartmentsOutsideTargetPolicy = selectedDepartments
      .filter(
        (department) =>
          (department.tierDepartmentPoolId || department.deployedFromTierId) &&
          department.templateId &&
          !targetDepartmentTemplateIds.has(department.templateId),
      )
      .map((department) => ({
        id: department.id,
        name: department.name,
        templateId: department.templateId,
      }));

    return {
      tenantId: tenant.id,
      tenantName: tenant.name,
      currentTier: {
        id: tenant.tier.id,
        name: tenant.tier.name,
        slug: tenant.tier.slug,
        maxAgents: tenant.tier.maxAgents,
      },
      targetTier: {
        id: newTier.id,
        name: newTier.name,
        slug: newTier.slug,
        maxAgents: newTier.maxAgents,
      },
      usage: {
        selectedAgents: selectedAgents.length,
        selectedDepartments: selectedDepartments.length,
      },
      compatibility: {
        canChange: blockingReasons.length === 0,
        blockingReasons,
      },
      impact: {
        agentsToProvision,
        departmentsToProvision,
        tierLinkedAgentsOutsideTargetPolicy,
        tierLinkedDepartmentsOutsideTargetPolicy,
      },
    };
  }

  async changeTier(tenantId: string, newTierId: string) {
    const tenant = await this.findOne(tenantId);
    const preview = await this.previewTierChange(tenantId, newTierId);
    if (!preview.compatibility.canChange) {
      throw new ConflictException(preview.compatibility.blockingReasons[0]);
    }

    const newTier = await this.prisma.tier.findUnique({
      where: { id: newTierId },
    });
    if (!newTier) {
      throw new NotFoundException(`Tier ${newTierId} not found`);
    }

    const updated = await this.prisma.tenant.update({
      where: { id: tenantId },
      data: { tierId: newTierId },
      include: { tier: true },
    });

    const oldTierName =
      (tenant as any).tier?.name ?? (tenant as any).tierId ?? 'unknown';
    this.logger.log(
      `Tenant ${tenant.slug} changed from tier ${oldTierName} to ${newTier.name}`,
    );
    return updated;
  }

  async suspend(id: string) {
    await this.findOne(id);
    return this.prisma.tenant.update({
      where: { id },
      data: { status: TenantStatus.SUSPENDED },
    });
  }
}
